def parse_duration(text):
    text = text.strip()
    if not text or not any(char in text for char in 'hms') or len(text) > 4:
        raise ValueError

    if 'h' not in text and 'm' in text:
        raise ValueError
    if 'h' in text and 's' in text and 'm' not in text:
        raise ValueError
    if 'h' in text and 'm' in text and text.index('h') > text.index('m'):
        raise ValueError
    if 'h' in text and 's' in text and text.index('h') > text.index('s'):
        raise ValueError
    if 'm' in text and 's' in text and text.index('m') > text.index('s'):
        raise ValueError

    parts = text.split()
    total_seconds = 0

    for part in parts:
        if 'h' in part:
            hours = int(part[:part.index('h')])
            total_seconds += hours * 3600
        elif 'm' in part:
            minutes = int(part[:part.index('m')])
            total_seconds += minutes * 60
        elif 's' in part:
            seconds = int(part.strip())
            total_seconds += seconds

    return total_seconds

def roman_to_int(s):
    roman_values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    i = 0
    while i < len(s):
        if i + 1 < len(s) and roman_values[s[i]] < roman_values[s[i + 1]]:
            total += roman_values[s[i + 1]] - roman_values[s[i]]
            i += 2
        else:
            total += roman_values[s[i]]
            i += 1
    return total

