def word_wrap(text, width):
    if not text.strip():
        return []

    words = text.split()
    lines = []
    current_line = ''

    for word in words:
        if len(current_line) + len(word) + 1 <= width:
            if current_line:
                current_line += ' ' + word
            else:
                current_line = word
        else:
            lines.append(current_line)
            current_line = word

    if current_line:
        lines.append(current_line)

    return lines
